SIM.write_text('from __future__ import annotations\nimport asyncio,json,os,time\nfrom pathlib import Path\nfrom time import perf_counter_ns\n\nfrom meteora_dlmm import quote as dlmm_quote_live\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.native_atomic_money_machine import core as c\nfrom qseries_v2.oracle_strategy_intelligence.solana_money import qsb059_gav_reverse_atomic as q59\n\nMIN_SIM_BPS=float(os.getenv("QARB_ATOMIC_SIM_MIN_BPS","20"))\nMAX_SIGNAL_AGE_MS=float(os.getenv("QARB_ATOMIC_SIM_MAX_SIGNAL_AGE_MS","750"))\nDEBOUNCE_SECONDS=float(os.getenv("QARB_ATOMIC_SIM_DEBOUNCE_SECONDS","2.0"))\nQUEUE_MAX=int(os.getenv("QARB_ATOMIC_SIM_QUEUE_MAX","64"))\nJOURNAL=Path("runtime_state/qseries/qarb_clean_bot/live_atomic_simulations.jsonl")\n\ndef _append(root,row):\n    p=Path(root)/JOURNAL\n    p.parent.mkdir(parents=True,exist_ok=True)\n    with p.open("a",encoding="utf-8") as f:\n        f.write(json.dumps(row,sort_keys=True,separators=(",",":"))+"\\n")\n\ndef _find_pair(state,signal):\n    token=signal["token"];pump=signal["buy_pool"];meteora=signal["sell_pool"]\n    for p in state["pairs"]:\n        if p.token==token and p.pump_pool==pump and p.meteora_pool==meteora:\n            return p\n    raise RuntimeError("LIVE_PAIR_BINDING_NOT_FOUND")\n\ndef _bound_meta(pair):\n    return {\n      "address":pair.meteora_pool,\n      "token_x":pair.token_x,\n      "token_y":pair.token_y,\n      "decimals_x":pair.decimals_x,\n      "decimals_y":pair.decimals_y,\n    }\n\ndef _live_dlmm_quote(pair,amount_in,input_mint):\n    if input_mint==pair.token_x: swap_for_y=True\n    elif input_mint==pair.token_y: swap_for_y=False\n    else: raise RuntimeError("DLMM_DIRECTION")\n    q=dlmm_quote_live(pair.dlmm_state,amount_in=int(amount_in),swap_for_y=swap_for_y,strict=True)\n    if not getattr(q,"complete",False) or int(getattr(q,"remaining_in",0) or 0):\n        raise RuntimeError("DLMM_PARTIAL")\n    return {\n      "raw_out":int(q.amount_out),\n      "bins_crossed":max(1,int(getattr(q,"bins_crossed",1) or 1)),\n      "swap_for_y":swap_for_y,\n    }\n\ndef compose_bound(user,pair,start_sol):\n    start=int(round(float(start_sol)*1e9))\n    p_ixs,alts,pump_token_out=q59.api_pump_route(user,pair.token,start)\n    pump_bound=any(\n        a.get("pubkey")==pair.pump_pool\n        for ix in p_ixs\n        for a in (ix.get("accounts") or [])\n    )\n    if not pump_bound:\n        raise RuntimeError("PUMP_BINDING_DRIFT")\n    mq=_live_dlmm_quote(pair,pump_token_out,pair.token)\n    end=int(mq["raw_out"])\n    meta=_bound_meta(pair)\n    m_ix=q59.dlmm_reverse_ix(user,meta,pump_token_out,mq)\n    return {\n      "start_lamports":start,\n      "pump_token_out_raw":pump_token_out,\n      "meteora_end_lamports":end,\n      "pre_sim_net_lamports":end-start,\n      "pre_sim_bps":(end-start)/start*10000.0,\n      "alts":alts,\n      "candidates":q59.candidate_instruction_sets(p_ixs,m_ix),\n    }\n\ndef simulate_signal(root,state,signal):\n    if signal["buy_venue"]!="PUMPSWAP" or signal["sell_venue"]!="METEORA_DLMM":\n        return {"status":"UNSUPPORTED_DIRECTION","execution_authority":False}\n    if float(signal.get("event_to_decision_ms") or 0)>MAX_SIGNAL_AGE_MS:\n        return {"status":"STALE_SIGNAL","execution_authority":False}\n    if float(signal.get("net_bps") or 0)<MIN_SIM_BPS:\n        return {"status":"BELOW_SIM_GATE","execution_authority":False}\n\n    pair=_find_pair(state,signal)\n    kp,user=c.sim_identity()\n    route=compose_bound(user,pair,float(signal["size_sol"]))\n    bh=c.rpc("getLatestBlockhash",[{"commitment":"processed"}])["value"]["blockhash"]\n    winner,attempts=q59.attempt_candidate_simulations(user,kp,route,bh)\n    row={\n      "ts":time.time(),\n      "token":signal["token"],\n      "pump_pool":signal["buy_pool"],\n      "meteora_pool":signal["sell_pool"],\n      "size_sol":signal["size_sol"],\n      "local_net_sol":signal["net_sol"],\n      "local_bps":signal["net_bps"],\n      "pre_sim_net_sol":route["pre_sim_net_lamports"]/1e9,\n      "pre_sim_bps":route["pre_sim_bps"],\n      "winner":winner,\n      "attempts":attempts,\n      "profitable_simulation":bool(winner and winner.get("profitable")),\n      "sim_pnl_sol":None if not winner or winner.get("sim_pnl_lamports") is None else winner["sim_pnl_lamports"]/1e9,\n      "sim_bps":None if not winner else winner.get("sim_bps"),\n      "execution_authority":False,\n      "real_money_moved":False,\n    }\n    _append(root,row)\n    return row\n\nclass SimulationLane:\n    def __init__(self,root,state):\n        self.root=Path(root);self.state=state\n        self.q=asyncio.Queue(maxsize=QUEUE_MAX)\n        self.last={}\n        self.attempts=0;self.profitable=0;self.failures=0;self.drops=0;self.best=None\n\n    def submit(self,signal):\n        if signal["buy_venue"]!="PUMPSWAP" or signal["sell_venue"]!="METEORA_DLMM":\n            return False\n        now=time.monotonic()\n        key=(signal["token"],signal["buy_pool"],signal["sell_pool"],round(float(signal["size_sol"]),9))\n        if now-self.last.get(key,0.0)<DEBOUNCE_SECONDS:\n            return False\n        self.last[key]=now\n        try:self.q.put_nowait(dict(signal))\n        except asyncio.QueueFull:\n            self.drops+=1;return False\n        return True\n\n    async def worker(self,stop):\n        while not stop.is_set():\n            try:sig=await asyncio.wait_for(self.q.get(),timeout=.5)\n            except asyncio.TimeoutError:continue\n            self.attempts+=1\n            try:\n                row=await asyncio.to_thread(simulate_signal,self.root,self.state,sig)\n                if row.get("profitable_simulation"):\n                    self.profitable+=1\n                    if self.best is None or float(row.get("sim_pnl_sol") or -1e99)>float(self.best.get("sim_pnl_sol") or -1e99):\n                        self.best=row\n                    print("[ATOMIC_SIM_PROFIT] token=%s size=%.6f local=%+.9f_SOL sim=%+.9f_SOL sim_bps=%+.2f"%(\n                        row["token"][:10],row["size_sol"],row["local_net_sol"],\n                        row["sim_pnl_sol"],row["sim_bps"]),flush=True)\n                else:\n                    print("[ATOMIC_SIM_REJECT] token=%s size=%.6f local=%+.9f_SOL status=NO_PROFITABLE_SIM"%(\n                        sig["token"][:10],sig["size_sol"],sig["net_sol"]),flush=True)\n            except Exception as exc:\n                self.failures+=1\n                print("[ATOMIC_SIM_ERROR] token=%s %s:%s"%(\n                    sig["token"][:10],type(exc).__name__,exc),flush=True)\n',encoding='utf-8');py_compile.compile(str(SIM),doraise=True)

MOD=SUB/'persistent_profit_runtime.py'
MOD.write_text('from __future__ import annotations\nimport argparse,asyncio,json,os,signal,time\nfrom pathlib import Path\nfrom time import perf_counter_ns\n\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import merged_live_runtime as m\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot.live_atomic_simulation import SimulationLane\n\nHEARTBEAT_SECONDS=float(os.getenv("QARB_HEARTBEAT_SECONDS","15"))\nRECONNECT_MIN=float(os.getenv("QARB_WS_RECONNECT_MIN_SECONDS","1"))\nRECONNECT_MAX=float(os.getenv("QARB_WS_RECONNECT_MAX_SECONDS","30"))\nQUEUE_MAX=int(os.getenv("QARB_EVENT_QUEUE_MAX","20000"))\nMAX_PAIRS=int(os.getenv("QARB_PERSISTENT_MAX_PAIRS","12"))\n_STOP=False\n\ndef _stop(*_):\n    global _STOP\n    _STOP=True\n\ndef _p99(xs):\n    if not xs:return None\n    y=sorted(xs);return y[min(len(y)-1,int(len(y)*.99))]\n\ndef _best_text(best):\n    if not best:return "None"\n    return "%+.9f_SOL %+.2f_bps %s->%s"%(best["net_sol"],best["net_bps"],best["buy_venue"],best["sell_venue"])\n\ndef _process_event(state,ev,c,sim_lane):\n    a=ev["address"];tokens=set();priced=False\n    if a in state["preg"]:\n        i,k=state["preg"][a];p=state["pairs"][i]\n        try:\n            if m.pd.apply_account_event(p,k,a,ev["raw"],ev["slot"],ev["received_ns"]):\n                tokens.add(p.token);priced=True\n        except Exception:c["event_errors"]+=1\n    if a in state["creg"]:\n        i,d=state["creg"][a];dd,st=state["cstates"][i]\n        try:\n            if m.rc.update(st,dd,a,ev["raw"],ev["received_ns"]):\n                ep=m._cpmm_ep(dd,st)\n                if ep:tokens.add(ep.token);priced=True\n        except Exception:c["event_errors"]+=1\n    if not priced:\n        if a in state["observed"]:c["observed_only_events"]+=1\n        return\n    c["priced_events"]+=1\n    for token in tokens:\n        r=m.evaluate_token(token,state["eps"].get(token,()),state["landing"],ev["received_ns"])\n        if not r:continue\n        c["lat"].append(float(r["event_to_decision_ms"]))\n        if c["best"] is None or r["net_sol"]>c["best"]["net_sol"]:c["best"]=r\n        if r["qualified"]:\n            c["signals"]+=1\n            print("[HOT_SIGNAL] token=%s buy=%s sell=%s size=%.6f net=%+.9f SOL bps=%+.2f age_ms=%.3f"%(\n                token[:10],r["buy_venue"],r["sell_venue"],r["size_sol"],r["net_sol"],r["net_bps"],r["event_to_decision_ms"]),flush=True)\n            sim_lane.submit(r)\n\ndef _initial_scan(state,c,sim_lane):\n    now=perf_counter_ns()\n    for token,eps in state["eps"].items():\n        r=m.evaluate_token(token,eps,state["landing"],now)\n        if not r:continue\n        if c["best"] is None or r["net_sol"]>c["best"]["net_sol"]:c["best"]=r\n        if r["qualified"]:\n            c["signals"]+=1\n            print("[HOT_SIGNAL_INITIAL] token=%s buy=%s sell=%s size=%.6f net=%+.9f SOL bps=%+.2f"%(\n                token[:10],r["buy_venue"],r["sell_venue"],r["size_sol"],r["net_sol"],r["net_bps"]),flush=True)\n            sim_lane.submit(r)\n\nasync def _worker(index,addresses,q,c,stop):\n    import websockets\n    await asyncio.sleep(index*m.STAGGER_SECONDS)\n    delay=RECONNECT_MIN\n    while not stop.is_set():\n        by_id={i+1:a for i,a in enumerate(addresses)};submap={}\n        try:\n            async with websockets.connect(m.WS_URL,ping_interval=20,ping_timeout=20,close_timeout=3,max_size=8_000_000) as ws:\n                c["connections"]+=1\n                for req in m._req(addresses):\n                    if stop.is_set():break\n                    await ws.send(json.dumps(req,separators=(",",":")))\n                    if m.SUB_DELAY_MS>0:await asyncio.sleep(m.SUB_DELAY_MS/1000.0)\n                delay=RECONNECT_MIN\n                while not stop.is_set():\n                    try:raw=await asyncio.wait_for(ws.recv(),timeout=1.0)\n                    except asyncio.TimeoutError:continue\n                    msg=json.loads(raw)\n                    if "id" in msg and isinstance(msg.get("result"),int):\n                        a=by_id.get(int(msg["id"]))\n                        if a:submap[int(msg["result"])]=a;c["acks"]+=1\n                        continue\n                    ev=m._parse(msg,submap)\n                    if not ev:continue\n                    c["notifications"]+=1\n                    try:q.put_nowait(ev)\n                    except asyncio.QueueFull:c["queue_drops"]+=1\n        except asyncio.CancelledError:raise\n        except Exception as exc:\n            txt=f"{type(exc).__name__}: {exc}";c["reconnects"]+=1;c["last_ws_error"]=txt\n            low=txt.lower()\n            if "1013" in low or "rate limit" in low or "too many subscriptions" in low:c["rate_limit_disconnects"]+=1\n            print("[WS_RECOVER] shard=%d error=%s retry_in=%.1fs"%(index,txt,delay),flush=True)\n            await asyncio.sleep(delay);delay=min(RECONNECT_MAX,max(RECONNECT_MIN,delay*2))\n\nasync def serve(root,max_seconds=None):\n    root=Path(root);m.pd.MAX_PAIRS=MAX_PAIRS\n    state=m.prepare(root);caps=m.capability(state);shards=m._shards(state["addresses"])\n    c={"acks":0,"notifications":0,"priced_events":0,"observed_only_events":0,"signals":0,\n       "event_errors":0,"queue_drops":0,"connections":0,"reconnects":0,\n       "rate_limit_disconnects":0,"last_ws_error":None,"lat":[],"best":None}\n    sim_lane=SimulationLane(root,state)\n    print("[QARB-023] PERSISTENT LIVE ARBITRAGE + ATOMIC SIMULATION GATE",flush=True)\n    print("[DISCOVERY] one startup hydration only",flush=True)\n    print("[HOT] signal path remains in-memory; simulation runs on background lane",flush=True)\n    print("[SIM] PumpSwap->Meteora DLMM qualified signals -> exact bound atomic simulateTransaction",flush=True)\n    print("[CAPABILITY] "+json.dumps(caps,sort_keys=True),flush=True)\n    print("[LIVE] accounts=%d shards=%d priced_tokens=%d max_pairs=%d"%(len(state["addresses"]),len(shards),len(state["eps"]),MAX_PAIRS),flush=True)\n    print("[MODE] simulation gate only execution_authority=FALSE real_money_moved=FALSE",flush=True)\n\n    q=asyncio.Queue(maxsize=QUEUE_MAX);stop=asyncio.Event()\n    sim_task=asyncio.create_task(sim_lane.worker(stop))\n    _initial_scan(state,c,sim_lane)\n    workers=[asyncio.create_task(_worker(i,s,q,c,stop)) for i,s in enumerate(shards)]\n    started=time.monotonic();last_hb=started;last_n=0\n    try:\n        while not stop.is_set():\n            if _STOP:break\n            if max_seconds is not None and time.monotonic()-started>=float(max_seconds):break\n            try:ev=await asyncio.wait_for(q.get(),timeout=.25);_process_event(state,ev,c,sim_lane)\n            except asyncio.TimeoutError:pass\n            now=time.monotonic()\n            if now-last_hb>=HEARTBEAT_SECONDS:\n                span=max(.001,now-last_hb);eps=(c["notifications"]-last_n)/span\n                sb=None if sim_lane.best is None else sim_lane.best.get("sim_pnl_sol")\n                print("[HEARTBEAT] uptime_s=%d notifications=%d eps=%.2f priced_events=%d signals=%d best=%s p99_ms=%s sim_attempts=%d sim_profitable=%d sim_best=%s sim_failures=%d reconnects=%d rate_limits=%d"%(\n                    int(now-started),c["notifications"],eps,c["priced_events"],c["signals"],_best_text(c["best"]),\n                    str(_p99(c["lat"])),sim_lane.attempts,sim_lane.profitable,str(sb),sim_lane.failures,\n                    c["reconnects"],c["rate_limit_disconnects"]),flush=True)\n                last_hb=now;last_n=c["notifications"]\n    finally:\n        stop.set()\n        for t in workers:t.cancel()\n        sim_task.cancel()\n        await asyncio.gather(*workers,sim_task,return_exceptions=True)\n\n    return {"notifications":c["notifications"],"priced_events":c["priced_events"],"signals":c["signals"],\n            "best":c["best"],"sim_attempts":sim_lane.attempts,"sim_profitable":sim_lane.profitable,\n            "sim_best":sim_lane.best,"sim_failures":sim_lane.failures,"sim_drops":sim_lane.drops,\n            "reconnects":c["reconnects"],"rate_limit_disconnects":c["rate_limit_disconnects"],\n            "p99_event_to_decision_ms":_p99(c["lat"]),"execution_authority":False,"real_money_moved":False}\n\ndef main(argv=None):\n    ap=argparse.ArgumentParser();ap.add_argument("--seconds",type=float,default=None,help="omit for continuous 24/7")\n    a=ap.parse_args(argv)\n    signal.signal(signal.SIGINT,_stop)\n    if hasattr(signal,"SIGTERM"):signal.signal(signal.SIGTERM,_stop)\n    r=asyncio.run(serve(Path.cwd(),a.seconds))\n    print("[RESULT] "+json.dumps(r,sort_keys=True),flush=True);return r\n\nif __name__=="__main__":main()\n',encoding='utf-8');py_compile.compile(str(MOD),doraise=True)

TEST=ROOT/'test_qarb_023_live_hot_signal_atomic_simulation_gate.py'
TEST.write_text('import asyncio,unittest\nfrom types import SimpleNamespace\nfrom time import perf_counter_ns\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot.live_atomic_simulation import SimulationLane,_bound_meta\n\nclass T(unittest.TestCase):\n    def test_bound_meta_uses_live_pair(self):\n        p=SimpleNamespace(meteora_pool="M",token_x="X",token_y="Y",decimals_x=9,decimals_y=6)\n        m=_bound_meta(p)\n        self.assertEqual(m["address"],"M");self.assertEqual(m["token_x"],"X")\n        print("[PASS] atomic simulation binds exact live Meteora pool instead of rediscovery")\n\n    def test_debounce_prevents_sim_storm(self):\n        s=SimpleNamespace()\n        lane=SimulationLane(".",s)\n        sig={"token":"T","buy_pool":"P","sell_pool":"M","size_sol":1.0,\n             "buy_venue":"PUMPSWAP","sell_venue":"METEORA_DLMM","net_sol":.1,"net_bps":100}\n        self.assertTrue(lane.submit(sig));self.assertFalse(lane.submit(sig))\n        print("[PASS] duplicate hot signals are debounced before RPC simulation")\n\n    def test_unsupported_direction_not_queued(self):\n        lane=SimulationLane(".",SimpleNamespace())\n        sig={"token":"T","buy_pool":"P","sell_pool":"M","size_sol":1.0,\n             "buy_venue":"METEORA_DLMM","sell_venue":"PUMPSWAP","net_sol":.1,"net_bps":100}\n        self.assertFalse(lane.submit(sig))\n        print("[PASS] unsupported reverse direction fails closed")\n\nif __name__=="__main__":unittest.main(verbosity=2)\n',encoding='utf-8');py_compile.compile(str(TEST),doraise=True)

